using Unciv.Logic;
using Unciv.Net.Identity;

namespace Unciv.Utils;

/// <summary>
/// T230: the per-game host secret for state-based randomness (combat, captures, espionage, barbarian placement, ...).
/// Where it lives: generated by the host once at game start, kept in the host's game store (game.json beside the snapshot, T176) and in
/// the command-log header, which replay needs. It is never serialized with <see cref="GameInfo"/> (so saves, snapshots, filtered views and
/// the full-state hash do not contain it) and is re-applied with <see cref="ApplyTo"/> after every load or restore. Not hosting = 0 = Kotlin behaviour.
/// </summary>
public static class HostSecret
{
    /// <summary>A fresh non-zero 64-bit secret from the OS CSPRNG. Host only; not deterministic by design.</summary>
    public static long Generate(ISecureRandom? random = null)
    {
        var bytes = new byte[8];
        while (true)
        {
            (random ?? SystemSecureRandom.Instance).Fill(bytes);
            var secret = BitConverter.ToInt64(bytes, 0);
            if (secret != 0) return secret;
        }
    }

    /// <summary>Installs <paramref name="secret"/> on a started or loaded game. Call after <c>StartNewGame</c> and after every load.</summary>
    public static GameInfo ApplyTo(GameInfo game, long secret)
    {
        game.RandomSalt = secret;
        return game;
    }
}
